
DROP DATABASE IF EXISTS autocare;
CREATE DATABASE autocare CHARACTER SET utf8mb4;
USE autocare;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE customers (
  id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, phone VARCHAR(15) NOT NULL UNIQUE,
  email VARCHAR(120), address VARCHAR(255), phone_verified TINYINT NOT NULL DEFAULT 0,
  created_at VARCHAR(30) NOT NULL, last_login VARCHAR(30));
CREATE TABLE staff (
  id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, full_name VARCHAR(100) NOT NULL,
  role ENUM('admin','advisor','technician') NOT NULL, password_hash VARCHAR(255) NOT NULL,
  active TINYINT NOT NULL DEFAULT 1, failed_attempts INT NOT NULL DEFAULT 0, locked_until VARCHAR(30),
  created_at VARCHAR(30) NOT NULL);
CREATE TABLE otps (
  id INT AUTO_INCREMENT PRIMARY KEY, phone VARCHAR(15) NOT NULL, code_hash VARCHAR(255) NOT NULL,
  purpose VARCHAR(20) NOT NULL, created_at VARCHAR(30) NOT NULL, expires_at VARCHAR(30) NOT NULL,
  attempts INT NOT NULL DEFAULT 0, used TINYINT NOT NULL DEFAULT 0, INDEX ix_otps_phone (phone));
CREATE TABLE vehicles (
  id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, reg_no VARCHAR(20) NOT NULL UNIQUE,
  make VARCHAR(50), model VARCHAR(60) NOT NULL, year INT, fuel VARCHAR(20), odometer INT NOT NULL DEFAULT 0,
  last_reminded VARCHAR(30), created_at VARCHAR(30) NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE services (
  id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255),
  base_price DECIMAL(10,2) NOT NULL, duration_min INT NOT NULL DEFAULT 60, interval_km INT NOT NULL DEFAULT 0,
  interval_months INT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE bookings (
  id INT AUTO_INCREMENT PRIMARY KEY, ref VARCHAR(20) NOT NULL UNIQUE, customer_id INT NOT NULL, vehicle_id INT NOT NULL,
  booking_date VARCHAR(10) NOT NULL, time_slot VARCHAR(5) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Booked',
  notes TEXT, pickup TINYINT NOT NULL DEFAULT 0, odometer_in INT, technician_id INT,
  discount_pct DECIMAL(5,2) NOT NULL DEFAULT 0, subtotal DECIMAL(10,2) NOT NULL DEFAULT 0,
  discount DECIMAL(10,2) NOT NULL DEFAULT 0, tax DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(10,2) NOT NULL DEFAULT 0,
  payment_status VARCHAR(20) NOT NULL DEFAULT 'Unpaid', payment_method VARCHAR(20), paid_at VARCHAR(30),
  rating INT, feedback TEXT, source VARCHAR(20) NOT NULL DEFAULT 'online',
  created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL,
  INDEX ix_bookings_date (booking_date), INDEX ix_bookings_status (status),
  FOREIGN KEY (customer_id) REFERENCES customers(id), FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
  FOREIGN KEY (technician_id) REFERENCES staff(id));
CREATE TABLE booking_items (
  id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, service_id INT, name VARCHAR(80) NOT NULL,
  price DECIMAL(10,2) NOT NULL, qty INT NOT NULL DEFAULT 1,
  FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY (service_id) REFERENCES services(id));
CREATE TABLE status_history (
  id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, status VARCHAR(30) NOT NULL, note VARCHAR(255),
  staff_id INT, created_at VARCHAR(30) NOT NULL, INDEX ix_history_booking (booking_id),
  FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY (staff_id) REFERENCES staff(id));
CREATE TABLE maintenance (
  id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, booking_id INT, service_date VARCHAR(10) NOT NULL,
  odometer INT NOT NULL, services VARCHAR(255) NOT NULL, cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  next_due_date VARCHAR(10), next_due_km INT, source VARCHAR(20) NOT NULL DEFAULT 'workshop',
  FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE, FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE SET NULL);
CREATE TABLE notifications (
  id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, title VARCHAR(150) NOT NULL, body TEXT, link VARCHAR(120),
  is_read TINYINT NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, INDEX ix_notif_customer (customer_id, is_read),
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE);

SET FOREIGN_KEY_CHECKS=1;
SELECT 'AutoCare database loaded' AS result;
